package com.queryx.database.entities;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="investigations") public class Investigation { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="investigation_number",nullable=false,unique=true,length=50) private String investigationNumber; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="complaint_id",nullable=false) private Complaint complaint; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="assigned_user_id") private User assignedUser; @Column(nullable=false,length=200) private String title; private String summary; @Column(nullable=false,length=30) private String status; @Column(name="started_at",nullable=false) private OffsetDateTime startedAt; @Column(name="closed_at") private OffsetDateTime closedAt; public UUID getId(){return id;} public String getInvestigationNumber(){return investigationNumber;} public void setInvestigationNumber(String v){investigationNumber=v;} public Complaint getComplaint(){return complaint;} public void setComplaint(Complaint v){complaint=v;} public User getAssignedUser(){return assignedUser;} public void setAssignedUser(User v){assignedUser=v;} }
